const localizedNodes = englishPage.flatMap(([selector,en])=>[...document.querySelectorAll(selector)].map(node=>({node,pt:node.innerHTML,en})));
const localizedAttributes = englishAttributes.flatMap(([selector,attribute,en])=>[...document.querySelectorAll(selector)].map(node=>({node,attribute,pt:node.getAttribute(attribute),en})));
let currentLanguage = 'pt';
function setLanguage(language, {persist=false,updateUrl=false}={}) {
  currentLanguage=language==='en'?'en':'pt';
  const copy=languageCopy[currentLanguage];
  for(const entry of localizedNodes)entry.node.innerHTML=entry[currentLanguage];
  for(const entry of localizedAttributes)entry.node.setAttribute(entry.attribute,entry[currentLanguage]);
  document.documentElement.lang=currentLanguage==='en'?'en':'pt-BR';
  document.title=copy.title;
  document.querySelector('meta[name="description"]').content=copy.description;
  document.querySelector('meta[property="og:title"]').content=copy.title;
  document.querySelector('meta[property="og:description"]').content=copy.social;
  document.querySelector('meta[property="og:locale"]').content=currentLanguage==='en'?'en_US':'pt_BR';
  document.querySelector('.language-control').setAttribute('aria-label',copy.language);
  document.querySelectorAll('[data-language]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.language===currentLanguage)));
  const menu=document.querySelector('.menu-toggle');menu.setAttribute('aria-label',menu.getAttribute('aria-expanded')==='true'?copy.closeMenu:copy.openMenu);
  document.querySelector('.close-dialog').setAttribute('aria-label',copy.closeProject);
  document.querySelector('#copy-status').textContent='';
  if(persist){try{localStorage.setItem('marco-portfolio-language',currentLanguage);}catch{/* Language selection still works if storage is unavailable. */}}
  if(updateUrl){const url=new URL(location.href);url.searchParams.set('lang',currentLanguage);history.replaceState(null,'',url);}
}
let preferredLanguage='pt';
try{preferredLanguage=localStorage.getItem('marco-portfolio-language')||'pt';}catch{/* Use Portuguese when storage is unavailable. */}
const requestedLanguage=new URL(location.href).searchParams.get('lang');
if(requestedLanguage==='pt'||requestedLanguage==='en')preferredLanguage=requestedLanguage;
setLanguage(preferredLanguage);
document.querySelectorAll('[data-language]').forEach(button=>button.addEventListener('click',()=>setLanguage(button.dataset.language,{persist:true,updateUrl:true})));
